import{_ as s,C as d,o,c as n,a0 as r,b as i,w as a,a as l,E as h,a1 as u}from"./chunks/framework.D7EjqxMK.js";const R=JSON.parse('{"title":"03 · ROS 2 安全标准与自动驾驶","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/05_前沿趋势/03_ROS2安全标准与自动驾驶.md","filePath":"08-ros/05_前沿趋势/03_ROS2安全标准与自动驾驶.md"}'),S={name:"08-ros/05_前沿趋势/03_ROS2安全标准与自动驾驶.md"};function c(g,t,A,_,E,b){const e=d("Mermaid");return o(),n("div",null,[t[1]||(t[1]=r('<h1 id="_03-·-ros-2-安全标准与自动驾驶" tabindex="-1">03 · ROS 2 安全标准与自动驾驶 <a class="header-anchor" href="#_03-·-ros-2-安全标准与自动驾驶" aria-label="Permalink to &quot;03 · ROS 2 安全标准与自动驾驶&quot;">​</a></h1><blockquote><p><strong>位置</strong>：08-ROS / 05_前沿趋势 <strong>难度</strong>：⭐（偏行业判断与架构选型，不涉及深入认证流程） <strong>前置知识</strong>：<a href="./../03_高级话题/05_ROS2安全架构(SROS2).html">模块三：ROS 2 安全架构（DDS-Security/SROS 2）</a>、<a href="./../02_核心模块/">模块二：DDS 与 QoS</a><strong>最后更新</strong>：2026-08-25</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>自动驾驶是 ROS 2 在&quot;产业侧&quot;最有想象空间、也最苛刻的落地场景。这里的核心矛盾在于：ROS 2 天生是一个<strong>研究/原型友好、但默认不承诺功能安全（Functional Safety）与确定性</strong>的中间件，而车规量产要求 <strong>ISO 26262（道路车辆功能安全）</strong> 下的可认证、可追溯、确定性行为。因此，自动驾驶方向的 ROS 2 前沿，本质是两条线索：</p><ol><li><strong>用 ROS 2 做原型/验证/仿真</strong>（研究、测试、数据回灌）——已经很成熟；</li><li><strong>把 ROS 2 或它的衍生品推进到&quot;可认证&quot;</strong>——由 Apex.AI 等公司推动，仍有大量工作，本文只陈述可核实的公开事实。</li></ol><hr><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><h3 id="_2-1-dds-security-通信层的安全底座" tabindex="-1">2.1 DDS-Security：通信层的安全底座 <a class="header-anchor" href="#_2-1-dds-security-通信层的安全底座" aria-label="Permalink to &quot;2.1 DDS-Security：通信层的安全底座&quot;">​</a></h3><p>ROS 2 通过 DDS-Security 提供<strong>身份认证、访问控制、加密</strong>（详见 <a href="./../03_高级话题/05_ROS2安全架构(SROS2).html">模块三：ROS 2 安全架构</a>）。在自动驾驶栈里，它的作用是防止<strong>未授权节点</strong>订阅感知/控制话题或注入恶意指令——这是&quot;多源软件栈&quot;上车的最低安全门槛，但它只解决通信安全，<strong>不解决功能安全</strong>。</p><h3 id="_2-2-iso-26262-asil-功能安全等级" tabindex="-1">2.2 ISO 26262 / ASIL：功能安全等级 <a class="header-anchor" href="#_2-2-iso-26262-asil-功能安全等级" aria-label="Permalink to &quot;2.2 ISO 26262 / ASIL：功能安全等级&quot;">​</a></h3><p>ISO 26262 针对道路车辆电子电气系统的功能安全，按风险划分 <strong>ASIL A–D</strong>（D 最高）。ROS 2 原版并不自带 ASIL 认证；把 ROS 2 用于安全相关功能，需要<strong>衍生实现 + 认证证据链</strong>。</p><h3 id="_2-3-确定性与实时性" tabindex="-1">2.3 确定性与实时性 <a class="header-anchor" href="#_2-3-确定性与实时性" aria-label="Permalink to &quot;2.3 确定性与实时性&quot;">​</a></h3><p>车规控制要求<strong>确定性调度、有界延迟</strong>。ROS 2 通过 executor 回调、QoS、实时内核（PREEMPT_RT）等可以接近实时，但&quot;默认 Linux + 默认 DDS&quot;不提供硬实时保证——这是 ROS 2 上车必须显式处理的问题。</p><h3 id="_2-4-安全网关-safety-gateway-模式" tabindex="-1">2.4 安全网关（Safety Gateway）模式 <a class="header-anchor" href="#_2-4-安全网关-safety-gateway-模式" aria-label="Permalink to &quot;2.4 安全网关（Safety Gateway）模式&quot;">​</a></h3><p>一个工程上常用的隔离手段：把系统划分为<strong>信任域</strong>（安全关键、确定性）与<strong>非信任域</strong>（研究/第三方/L 大模型节点），中间用一个<strong>安全网关节点</strong>做白名单过滤、速率限制、越界拦截，只放行合法的服务/动作请求。</p><hr><h2 id="_3-技术原理-现状分析" tabindex="-1">3. 技术原理 / 现状分析 <a class="header-anchor" href="#_3-技术原理-现状分析" aria-label="Permalink to &quot;3. 技术原理 / 现状分析&quot;">​</a></h2><h3 id="_3-1-ros-2-iso-26262-公开工作现状-已核实" tabindex="-1">3.1 ROS 2 + ISO 26262：公开工作现状（已核实） <a class="header-anchor" href="#_3-1-ros-2-iso-26262-公开工作现状-已核实" aria-label="Permalink to &quot;3.1 ROS 2 + ISO 26262：公开工作现状（已核实）&quot;">​</a></h3><ul><li><strong>Apex.AI</strong>（apex.ai，公司官网可查）提供 <strong>Apex.OS</strong>——一个面向量产自动驾驶的软件平台，官方定位为&quot;通过 ISO 26262 ASIL-D 认证的 ROS 2 衍生实现&quot;。这是当前&quot;ROS 2 路线走向车规&quot;最直接的商业代表。</li><li><strong>社区讨论</strong>：Open Robotics Discourse 存在专题讨论《How to enable ROS to pass the safety certification of the automotive industry?》（discourse.openrobotics.org/t/27819），可见&quot;ROS 过车规认证&quot;是社区持续关注但<strong>尚无官方统一方案</strong>的话题。</li></ul><blockquote><p>现状判断：<strong>&quot;原版 ROS 2 整体通过 ISO 26262&quot;目前没有公开可查的官方认证案例</strong>；公开路径是&quot;衍生实现（Apex.OS）+ 针对性认证&quot;，以及&quot;把 ROS 2 限定在非安全相关/ASIL-QM 环节&quot;。其余声称请视为待验证。</p></blockquote><h3 id="_3-2-飞行与自动驾驶栈中的-ros-2-角色" tabindex="-1">3.2 飞行与自动驾驶栈中的 ROS 2 角色 <a class="header-anchor" href="#_3-2-飞行与自动驾驶栈中的-ros-2-角色" aria-label="Permalink to &quot;3.2 飞行与自动驾驶栈中的 ROS 2 角色&quot;">​</a></h3><h4 id="px4-ros-2-已核实" tabindex="-1">PX4 + ROS 2（已核实） <a class="header-anchor" href="#px4-ros-2-已核实" aria-label="Permalink to &quot;PX4 + ROS 2（已核实）&quot;">​</a></h4><p>PX4 自动驾驶仪（无人机/无人车飞控）与 ROS 2 的桥接有<strong>官方文档</strong>：PX4 User Guide 的 <code>ros/ros2_comm.md</code> 说明 PX4 通过 <strong>uXRCE-DDS</strong>（在 ROS 2 侧即 <code>microdds_client</code> 或 <code>ros2</code> + XRCE 支持）与 ROS 2 节点通信。典型分工：<strong>PX4 负责底层姿态/位置控制（安全关键），ROS 2 负责上层规划、感知、任务逻辑</strong>——这是一个清晰的&quot;确定性底层 + 灵活上层&quot;分层范例。</p><h4 id="autoware-已核实" tabindex="-1">Autoware（已核实） <a class="header-anchor" href="#autoware-已核实" aria-label="Permalink to &quot;Autoware（已核实）&quot;">​</a></h4><p>Autoware 是<strong>基于 ROS 2 的开源自动驾驶软件栈</strong>（autowarefoundation.github.io 提供官方文档），覆盖感知、定位、规划、控制全链路，被广泛用于研究、仿真与商业衍生（如 AutoCore 的 PCU，见 96boards 博客）。它是&quot;ROS 2 作为自动驾驶主框架&quot;最成熟的开源证据。</p><h3 id="_3-3-车厂-企业的真实公开案例-已核实-其余标注待验证" tabindex="-1">3.3 车厂/企业的真实公开案例（已核实，其余标注待验证） <a class="header-anchor" href="#_3-3-车厂-企业的真实公开案例-已核实-其余标注待验证" aria-label="Permalink to &quot;3.3 车厂/企业的真实公开案例（已核实，其余标注待验证）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主体</th><th>公开事实</th><th>来源</th></tr></thead><tbody><tr><td>Apex.AI</td><td>Apex.OS 定位为 ASIL-D 认证的 ROS 2 衍生 OS</td><td>apex.ai/about</td></tr><tr><td>AutoCore</td><td>基于 Autoware 的自动驾驶控制器 PCU</td><td>96boards.org 博客</td></tr><tr><td>ADLINK</td><td>提供 ROS 2 工业控制器/计算机（ROScube 等）</td><td>adlinktech.com</td></tr><tr><td>Woven by Toyota</td><td>Toyota 软件子公司，公开活动涉及 ROS/机器人软件</td><td>woven.toyota</td></tr></tbody></table><blockquote><p>⚠️ 说明：<strong>具体整车厂&quot;某款量产车使用了 ROS 2&quot;的公开声明较少</strong>，多为&quot;研究/原型使用 ROS 2 + 量产走衍生实现&quot;。本文不把任何未经核实的量产车型断言写死，相关细节统一视为&quot;公开资料有限，待补充验证&quot;。</p></blockquote><hr><h2 id="_4-实践指南-当前可落地路径" tabindex="-1">4. 实践指南（当前可落地路径） <a class="header-anchor" href="#_4-实践指南-当前可落地路径" aria-label="Permalink to &quot;4. 实践指南（当前可落地路径）&quot;">​</a></h2><h3 id="_4-1-分层落地方案" tabindex="-1">4.1 分层落地方案 <a class="header-anchor" href="#_4-1-分层落地方案" aria-label="Permalink to &quot;4.1 分层落地方案&quot;">​</a></h3><ol><li><strong>非安全侧</strong>：直接用标准 ROS 2（Autoware、仿真、数据回灌、感知原型）——零门槛；</li><li><strong>桥接安全侧</strong>：PX4 + ROS 2 官方桥接，让确定性飞控与灵活上层解耦；</li><li><strong>安全关键侧</strong>：评估 Apex.OS 等衍生实现，并配套功能安全流程（HARA、安全分析、验证证据链）；</li><li><strong>通信安全</strong>：启用 DDS-Security（模块三），配置身份/权限/加密。</li></ol><h3 id="_4-2-安全网关模式示意" tabindex="-1">4.2 安全网关模式示意 <a class="header-anchor" href="#_4-2-安全网关模式示意" aria-label="Permalink to &quot;4.2 安全网关模式示意&quot;">​</a></h3>',34)),(o(),i(u,null,{default:a(()=>[h(e,{id:"mermaid-195",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20Trusted%5B%22%E4%BF%A1%E4%BB%BB%E5%9F%9F%EF%BC%88%E7%A1%AE%E5%AE%9A%E6%80%A7%2F%E5%AE%89%E5%85%A8%E5%85%B3%E9%94%AE%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20A%5B%22%E6%8E%A7%E5%88%B6%E8%8A%82%E7%82%B9%EF%BC%88%E8%A7%84%E5%88%92%2F%E6%8E%A7%E5%88%B6%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20B%5B%22%E6%84%9F%E7%9F%A5%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Untrusted%5B%22%E9%9D%9E%E4%BF%A1%E4%BB%BB%E5%9F%9F%EF%BC%88%E7%AC%AC%E4%B8%89%E6%96%B9%20%2F%20LLM%20%2F%20%E7%A0%94%E7%A9%B6%E8%8A%82%E7%82%B9%EF%BC%89%22%5D%0A%20%20%20%20%20%20%20%20C%5B%22%E5%A4%96%E9%83%A8%E8%8A%82%E7%82%B9%20%2F%20LLM%20%E5%8A%A9%E6%89%8B%22%5D%0A%20%20%20%20%20%20%20%20D%5B%22%E6%95%B0%E6%8D%AE%E9%87%87%E9%9B%86%E8%8A%82%E7%82%B9%22%5D%0A%20%20%20%20end%0A%20%20%20%20G%5B%22%E5%AE%89%E5%85%A8%E7%BD%91%E5%85%B3%E8%8A%82%E7%82%B9%3Cbr%2F%3E(%E7%99%BD%E5%90%8D%E5%8D%95%20%2F%20%E9%80%9F%E7%8E%87%E9%99%90%E5%88%B6%20%2F%20%E8%B6%8A%E7%95%8C%E6%8B%A6%E6%88%AA)%22%5D%0A%20%20%20%20C%20--%3E%20G%0A%20%20%20%20D%20--%3E%20G%0A%20%20%20%20G%20--%3E%7C%22%E4%BB%85%E6%94%BE%E8%A1%8C%E5%90%88%E6%B3%95%E6%9C%8D%E5%8A%A1%2F%E5%8A%A8%E4%BD%9C%22%7C%20A%0A%20%20%20%20B%20-.-%3E%7C%22%E5%8F%AA%E8%AF%BB%E6%95%B0%E6%8D%AE%22%7C%20D%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r('<blockquote><p>网关通常实现为：只暴露少量 <code>.srv/.action</code> 白名单、校验参数范围、对控制类请求限流与超时、记录审计日志。示例架构，需按实际框架实现。</p></blockquote><hr><h2 id="_5-方案对比" tabindex="-1">5. 方案对比 <a class="header-anchor" href="#_5-方案对比" aria-label="Permalink to &quot;5. 方案对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>安全等级可达</th><th>确定性</th><th>工程量</th><th>适用场景</th></tr></thead><tbody><tr><td>标准 ROS 2（默认 DDS）</td><td>QM / 研究</td><td>低</td><td>低</td><td>研究、仿真、原型</td></tr><tr><td>ROS 2 + DDS-Security</td><td>通信安全增强</td><td>低</td><td>中</td><td>多源节点隔离、防注入</td></tr><tr><td>ROS 2 + 实时内核 + QoS 调优</td><td>接近实时</td><td>中</td><td>中高</td><td>要求有界延迟的非 ASIL 环节</td></tr><tr><td>Apex.OS（ROS 2 衍生）</td><td>ASIL-D（厂商宣称）</td><td>高</td><td>高</td><td>量产安全关键功能</td></tr><tr><td>PX4 + ROS 2 桥接</td><td>底层飞控已有安全设计</td><td>中高</td><td>中</td><td>无人机/无人车上层规划</td></tr></tbody></table><p><strong>绝对不适用场景</strong>：直接把<strong>原版 ROS 2（默认 Linux + 默认 DDS，无认证证据链）<strong>用于需要 ISO 26262 ASIL 认证的</strong>安全关键功能</strong>并声称&quot;已满足车规&quot;。功能安全是流程 + 证据 + 实现共同作用的结果，不是换个中间件就能达成的。</p><hr><h2 id="_6-工具链" tabindex="-1">6. 工具链 <a class="header-anchor" href="#_6-工具链" aria-label="Permalink to &quot;6. 工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具/项目</th><th>作用</th><th>来源</th></tr></thead><tbody><tr><td>SROS 2 / DDS-Security</td><td>ROS 2 通信安全</td><td>模块三：ROS 2 安全架构</td></tr><tr><td>PX4 + uXRCE-DDS</td><td>飞控与 ROS 2 桥接</td><td>PX4 User Guide（ros2_comm.md）</td></tr><tr><td>Autoware</td><td>开源自动驾驶栈</td><td>autowarefoundation.github.io</td></tr><tr><td>micro-ROS Agent（XRCE）</td><td>PX4 桥接的 XRCE 侧</td><td>见 <a href="./01_microROS2与嵌入式.html">01 micro-ROS</a></td></tr><tr><td>Apex.OS</td><td>ROS 2 车规衍生实现（商业）</td><td>apex.ai</td></tr><tr><td>ADLINK ROScube</td><td>工业/车规 ROS 2 硬件</td><td>adlinktech.com</td></tr></tbody></table><hr><h2 id="_7-参考资料-均经核实" tabindex="-1">7. 参考资料（均经核实） <a class="header-anchor" href="#_7-参考资料-均经核实" aria-label="Permalink to &quot;7. 参考资料（均经核实）&quot;">​</a></h2><ul><li>PX4 ROS 2 通信官方文档：<a href="https://github.com/PX4/PX4-user_guide/blob/main/en/ros/ros2_comm.md" target="_blank" rel="noreferrer">https://github.com/PX4/PX4-user_guide/blob/main/en/ros/ros2_comm.md</a></li><li>Autoware 官方文档：<a href="https://autowarefoundation.github.io/autoware-documentation/" target="_blank" rel="noreferrer">https://autowarefoundation.github.io/autoware-documentation/</a></li><li>Apex.AI 官网：<a href="https://www.apex.ai/about" target="_blank" rel="noreferrer">https://www.apex.ai/about</a></li><li>ROS 车规安全认证社区讨论：<a href="https://discourse.openrobotics.org/t/how-to-enable-ros-to-pass-the-safety-certification-of-the-automotive-industry/27819" target="_blank" rel="noreferrer">https://discourse.openrobotics.org/t/how-to-enable-ros-to-pass-the-safety-certification-of-the-automotive-industry/27819</a></li><li>AutoCore PCU（96boards 博客）：<a href="https://www.96boards.org/blog/autocore_pcu_1/" target="_blank" rel="noreferrer">https://www.96boards.org/blog/autocore_pcu_1/</a></li><li>ADLINK ROS 2 方案：<a href="https://www.adlinktech.com/en/ros2-solution" target="_blank" rel="noreferrer">https://www.adlinktech.com/en/ros2-solution</a></li><li>Autoware Core（ROSCon JP 2025 演讲）：<a href="https://roscon.ros.org/jp/2025/presentations/11.pdf" target="_blank" rel="noreferrer">https://roscon.ros.org/jp/2025/presentations/11.pdf</a></li></ul><hr><h2 id="_8-学习路径" tabindex="-1">8. 学习路径 <a class="header-anchor" href="#_8-学习路径" aria-label="Permalink to &quot;8. 学习路径&quot;">​</a></h2><ol><li><strong>安全底座</strong>：先吃透 <a href="./../03_高级话题/05_ROS2安全架构(SROS2).html">模块三：ROS 2 安全架构</a> 的 DDS-Security/SROS 2；</li><li><strong>跑通分层栈</strong>：用 PX4 SITL + ROS 2 官方桥接跑一个仿真闭环，体会&quot;确定性底层 + 灵活上层&quot;；</li><li><strong>摸清车规</strong>：读 ISO 26262 概要与 Apex.AI 的公开材料，理解 ASIL、HARA、认证证据链；</li><li><strong>动手隔离</strong>：实现一个安全网关节点（白名单 + 限流 + 审计），体会隔离域设计；</li><li><strong>回看 LLM 风险</strong>：结合 <a href="./02_ROS2与大模型融合.html">02 · 大模型融合</a>，把 LLM 节点归入&quot;非信任域&quot;并走网关。</li></ol><hr><h2 id="_9-核心面试三问" tabindex="-1">9. 核心面试三问 <a class="header-anchor" href="#_9-核心面试三问" aria-label="Permalink to &quot;9. 核心面试三问&quot;">​</a></h2><p><strong>Q1：ROS 2 能用 DDS-Security 加密通信了，是不是就满足车规安全了？</strong> 答：不是。DDS-Security 解决的是<strong>通信安全</strong>（认证、授权、加密，防注入/窃听），而车规要求的是<strong>功能安全（ISO 26262）</strong>——即使通信完全可信，节点本身的逻辑错误、时序不可预测、失效行为仍会导致危险。二者是正交的：安全关键系统两者都要，但不能互相替代。</p><p><strong>Q2：为什么量产自动驾驶很少看到&quot;直接用原版 ROS 2&quot;，而是用 Apex.OS 这类衍生实现？</strong> 答：因为功能安全认证需要<strong>确定性、可追溯、可验证的实现与完整证据链</strong>，而原版 ROS 2 默认 Linux + DDS 不承诺硬实时与确定性，也难以整体取证。衍生实现（Apex.OS）保留 ROS 2 生态/接口兼容性，同时重构/加固底层以满足 ASIL 证据要求。原版 ROS 2 更多承担研究、原型与非安全环节。</p><p><strong>Q3：无人机里 PX4 和 ROS 2 是怎么分工的？为什么这么分？</strong> 答：PX4 负责底层姿态/位置控制与安全关键飞行逻辑（确定性、已在飞控侧做安全设计），ROS 2 负责上层规划、感知、任务编排。这么分是因为<strong>安全关键功能放在有确定性保证的飞控侧</strong>，而灵活多变的上层逻辑放在开发效率高的 ROS 2 侧，二者通过 uXRCE-DDS 桥接——这也是&quot;分层安全&quot;的典型体现。</p>',19))])}const p=s(S,[["render",c]]);export{R as __pageData,p as default};
